import fs from "node:fs";
import { spawn } from "node:child_process";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const jsPath  = path.join(__dirname, "drop-params.js");
const genPath = path.join(__dirname, "gen-drop-params-json.mjs");

// Existing output (generated by gen-drop-params-json.mjs)
const sharedJsonPath = path.join(__dirname, "drop-params.json");

// NEW: mirror output inside admin-ui/src so Parcel definitely sees it
const repoRoot = path.resolve(__dirname, "..", "..");
const adminMirrorPath = path.join(repoRoot, "admin-ui", "src", "drop-params.mirror.json");
const once = process.argv.includes("--once");

let t = null;
let requestedEpoch = 0;
let inFlight = false;

function writeFileAtomic(filePath, text) {
  const tmpPath = path.join(
    path.dirname(filePath),
    `.${path.basename(filePath)}.${process.pid}.${Date.now()}.tmp`
  );

  try {
    fs.writeFileSync(tmpPath, text, "utf8");
    fs.renameSync(tmpPath, filePath);
  } catch (err) {
    try {
      fs.unlinkSync(tmpPath);
    } catch {}
    throw err;
  }
}

function mirrorIntoAdmin() {
  const jsonText = fs.readFileSync(sharedJsonPath, "utf8");

  let prevMirror = null;
  try {
    prevMirror = fs.readFileSync(adminMirrorPath, "utf8");
  } catch (err) {
    if (err.code !== "ENOENT") throw err;
  }

  if (prevMirror === jsonText) {
    console.log("[drop-params] unchanged", adminMirrorPath);
    return;
  }

  writeFileAtomic(adminMirrorPath, jsonText);
  console.log("[drop-params] wrote", adminMirrorPath);
}

function generateOnce(epoch) {
  // IMPORTANT: wait for generator to finish before mirroring
  return new Promise((resolve) => {
    const child = spawn(process.execPath, [genPath], { stdio: "inherit" });

    child.on("exit", (code) => {
      if (code === 0) {
        if (epoch === requestedEpoch) {
          try {
            mirrorIntoAdmin();
          } catch (err) {
            console.warn("[drop-params] mirror stale:", err?.message || err);
            resolve(false);
            return;
          }
        }
        resolve(true);
      } else {
        console.warn("[drop-params] mirror stale: generator failed with code", code);
        resolve(false);
      }
    });

    child.on("error", (err) => {
      console.warn("[drop-params] mirror stale: generator spawn error:", err?.message || err);
      resolve(false);
    });
  });
}

function drainGenerateQueue() {
  if (inFlight) return;

  const epoch = requestedEpoch;
  inFlight = true;

  generateOnce(epoch).finally(() => {
    inFlight = false;
    if (epoch !== requestedEpoch) drainGenerateQueue();
  });
}

function generate() {
  requestedEpoch += 1;
  drainGenerateQueue();
}

if (once) {
  requestedEpoch += 1;
  generateOnce(requestedEpoch).then((ok) => {
    if (!ok) process.exitCode = 1;
  });
} else {
  console.log("[drop-params] watching", jsPath);
  generate();

  fs.watch(jsPath, () => {
    clearTimeout(t);
    t = setTimeout(generate, 150);
  });
}
